/**
 * @summary Run the automated demo flow
 */
export const getRunDemoUrl = () => {
  return `/api/demo/run`;
};

export const runDemo = async (
  options?: RequestInit,
): Promise<SuccessResponse> => {
  return customFetch<SuccessResponse>(getRunDemoUrl(), {
    ...options,
    method: "POST",
  });
};

export const getRunDemoMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof runDemo>>,
    TError,
    void,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof runDemo>>,
  TError,
  void,
  TContext
> => {
  const mutationKey = ["runDemo"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof runDemo>>,
    void
  > = () => {
    return runDemo(requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type RunDemoMutationResult = NonNullable<
  Awaited<ReturnType<typeof runDemo>>
>;

export type RunDemoMutationError = ErrorType<unknown>;

/**
 * @summary Run the automated demo flow
 */
export const useRunDemo = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof runDemo>>,
    TError,
    void,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof runDemo>>,
  TError,
  void,
  TContext
> => {
  return useMutation(getRunDemoMutationOptions(options));
};
